# The Phase 2, Step 4 exit fixture: one synthetic data file and one synthetic
# manuscript that reports six results from it, one per method family, each
# printed APA style from R's own numbers.
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_l1_exit_fixture.R
#
# Writes, next to this script:
#   exit_data.csv        a two-line '#' header, then the CSV. The data file is
#                        written, READ BACK with read.csv, and every result is
#                        computed on what was read.
#   exit_manuscript.txt  a two-line '#' header, then the manuscript text.
#
# The Rust test strips the '#' lines before the app's ingest and Level 0's
# reader see either file. Synthetic data only.

args <- commandArgs(trailingOnly = FALSE)
script <- sub("^--file=", "", args[grep("^--file=", args)])
here <- dirname(normalizePath(script))

header <- function(what) c(
  paste0("# Synthetic ", what, " for gaply's Level 1 exit test (Phase 2, Step 4)."),
  "# Generated by /usr/local/bin/Rscript make_l1_exit_fixture.R (do not edit by hand).")

# APA style: two decimals; no leading zero for r and p; p < .001 below it.
f2 <- function(x) sprintf("%.2f", x)
r2 <- function(x) sub("^(-?)0\\.", "\\1.", sprintf("%.2f", x))
pp <- function(p) if (p < .001) "p < .001" else paste0("p = ", sub("^0\\.", ".", sprintf("%.3f", p)))

set.seed(20261014)
n <- 40
g2 <- c(rep(1, 15), rep(2, 25))
d <- data.frame(
  y_t = round(c(rnorm(15, 10, 2), rnorm(25, 11.6, 2.4)), 2),
  g2 = g2,
  pre = round(rnorm(n, 20, 4), 2),
  y_a = NA, g3 = c(rep(1, 12), rep(2, 14), rep(3, 14)),
  x_r = round(rnorm(n, 0, 1), 2),
  y_r = NA, a2 = NA, b2 = NA,
  x1 = round(rnorm(n, 5, 2), 2), x2 = round(rnorm(n, 0, 1), 2), y_o = NA)
d$post <- round(d$pre + rnorm(n, 1.2, 2.2), 2)
d$y_a <- round(c(rnorm(12, 5, 1.5), rnorm(14, 6.1, 1.5), rnorm(14, 6.6, 1.5)), 2)
d$y_r <- round(0.45 * d$x_r + rnorm(n, 0, 0.9), 2)
d$a2 <- ifelse(runif(n) < 0.5, "no", "yes")
d$b2 <- ifelse(runif(n) < ifelse(d$a2 == "yes", 0.7, 0.35), "m", "f")
d$y_o <- round(2 + 0.5 * d$x1 + 0.6 * d$x2 + rnorm(n, 0, 1.6), 2)
d <- d[, c("y_t", "g2", "pre", "post", "y_a", "g3", "x_r", "y_r", "a2", "b2", "x1", "x2", "y_o")]

path <- file.path(here, "exit_data.csv")
write.csv(d, path, row.names = FALSE, quote = FALSE)
d <- read.csv(path, stringsAsFactors = FALSE)
writeLines(c(header("data"), readLines(path)), path)

t1 <- t.test(y_t ~ factor(g2), data = d, var.equal = TRUE)
pt <- t.test(d$pre, d$post, paired = TRUE)
av <- summary(aov(y_a ~ factor(g3), data = d))[[1]]
ct <- cor.test(d$x_r, d$y_r)
ch <- chisq.test(table(d$a2, d$b2), correct = FALSE)
lm1 <- summary(lm(y_o ~ x1 + x2, data = d))$fstatistic

lines <- c(
  "A Synthetic Study of Six Results", "",
  "Results", "",
  paste0("Reaction times differed between the two conditions, t(", t1$parameter, ") = ", f2(t1$statistic), ", ", pp(t1$p.value), "."), "",
  paste0("Scores changed from the first to the second session, t(", pt$parameter, ") = ", f2(pt$statistic), ", ", pp(pt$p.value), "."), "",
  paste0("Accuracy differed across the three groups, F(", av[["Df"]][1], ", ", av[["Df"]][2], ") = ", f2(av[["F value"]][1]), ", ", pp(av[["Pr(>F)"]][1]), "."), "",
  paste0("The two measures were related, r(", ct$parameter, ") = ", r2(ct$estimate), ", ", pp(ct$p.value), "."), "",
  paste0("Choice depended on condition, χ2(1, N = ", sum(table(d$a2, d$b2)), ") = ", f2(ch$statistic), ", ", pp(ch$p.value), "."), "",
  paste0("The model explained outcome scores, F(", lm1[["numdf"]], ", ", lm1[["dendf"]], ") = ", f2(lm1[["value"]]), ", ",
         pp(pf(lm1[["value"]], lm1[["numdf"]], lm1[["dendf"]], lower.tail = FALSE)), "."))
writeLines(c(header("manuscript"), lines), file.path(here, "exit_manuscript.txt"))
cat(paste(lines[grepl("=", lines)], collapse = "\n"), "\n")
